  "LO-277": {
    "title": "Voice Transformation: Active to Passive Voice 🔄⚙️",
    "desc": "Uses appropriate grammatical forms in communication (e.g. noun, pronoun, verb, determiners, time and tense, passivisation, adjective, adverb, etc.)",
    "subSkill": "Grammar in Use",
    "audio_script": "Students analyze scientific lab reports: 'Alexander Fleming discovered penicillin in 1928' vs 'Penicillin was discovered by Alexander Fleming in 1928'.",
    "story": "Students analyze scientific lab reports: 'Alexander Fleming discovered penicillin in 1928' vs 'Penicillin was discovered by Alexander Fleming in 1928'.",
    "instructions": [],
    "questions": [
      {
        "q": "Convert this active sentence into PASSIVE VOICE: 'The solar panels generated renewable electricity.'",
        "options": [
          "Solar panels were generating electricity.",
          "Renewable electricity generates solar panels.",
          "Renewable electricity was generated by the solar panels.",
          "Electricity had been generated solar panels."
        ],
        "answer": 2,
        "explain": "Passive structure: Object becomes subject (Renewable electricity) + auxiliary (was) + past participle (generated) + by agent!"
      },
      {
        "q": "Why is the PASSIVE VOICE frequently favored in formal scientific and newspaper reporting?",
        "options": [
          "It emphasizes the action, discovery, or observed phenomenon rather than the individual agent",
          "It complies with formal grammatical rules that strictly forbid active sentences in science",
          "It deliberately creates syntactic ambiguity so readers find experimental methods harder to read",
          "It is reserved exclusively for situations where the researcher has forgotten who ran the test"
        ],
        "answer": 0,
        "explain": "Passive voice establishes objective impartiality: 'The water was heated to 100°C' emphasizes the experiment, not the person."
      },
      {
        "q": "Which of these sentences is written in the PASSIVE VOICE?",
        "options": [
          "Thousands of eager visitors admired the intricate marble carving.",
          "The royal architect designed the magnificent red sandstone palace.",
          "Skilled artisan guilds carved the towering ceremonial entry gates.",
          "The historic monument was constructed during the fifteenth century."
        ],
        "answer": 3,
        "explain": "'Was constructed' uses the passive auxiliary + past participle construct."
      }
    ]
  },
