  "LO-287": {
    "title": "Algebraic Algebraists: Adding & Subtracting Expressions 🧮➕",
    "desc": "Adds/subtracts algebraic expressions",
    "subSkill": "Variables & Algebraic Expressions",
    "audio_script": "Students simplify polynomial expressions by combining like terms (terms with identical variable powers).",
    "story": "Students simplify polynomial expressions by combining like terms (terms with identical variable powers).",
    "instructions": [],
    "questions": [
      {
        "q": "Simplify by combining LIKE TERMS: (4x² + 3x - 5) + (2x² - 5x + 8) =",
        "options": [
          "6x⁴ - 2x² + 3",
          "6x² - 2x + 3",
          "6x² + 8x + 13",
          "8x² - 2x - 3"
        ],
        "answer": 1,
        "explain": "Combine corresponding like terms: (4+2)x² + (3-5)x + (-5+8) = 6x² - 2x + 3!"
      },
      {
        "q": "Subtract (2x - 3) from (5x + 7). Remember: (5x + 7) - (2x - 3) = 5x + 7 - 2x + 3 =",
        "options": [
          "7x + 10",
          "3x + 4",
          "3x + 10",
          "3x - 4"
        ],
        "answer": 2,
        "explain": "Distribute the negative sign: 5x - 2x = 3x, and 7 - (-3) = 7 + 3 = 10. Result: 3x + 10!"
      },
      {
        "q": "What is the numerical COEFFICIENT of the term '-7xy'?",
        "options": [
          "xy",
          "-7",
          "7",
          "-7xy"
        ],
        "answer": 1,
        "explain": "The numerical factor multiplying the variables is the coefficient: -7!"
      }
    ]
  },
