  "LO-295": {
    "title": "Triangle Angle Detective: Finding the Unknown Angle 🔺🔍",
    "desc": "Finds unknown angle of a triangle when its two angles are known",
    "subSkill": "Triangles & Congruence",
    "audio_script": "In a triangular solar panel bracket, two internal angles measure 65° and 75°. Engineer Kabir needs to calculate the third angle 'x'.",
    "story": "In a triangular solar panel bracket, two internal angles measure 65° and 75°. Engineer Kabir needs to calculate the third angle 'x'.",
    "instructions": [],
    "questions": [
      {
        "q": "Calculate the unknown angle 'x': 65° + 75° + x = 180°.",
        "options": [
          "30°",
          "50°",
          "45°",
          "40°"
        ],
        "answer": 3,
        "explain": "The angle sum of any triangle is 180°! 180° - (65° + 75°) = 180° - 140° = 40°."
      },
      {
        "q": "What does the EXTERIOR ANGLE THEOREM state for any triangle?",
        "options": [
          "An exterior angle of a triangle always equals ninety degrees regardless of interior shape",
          "An exterior angle is equal to the total sum of all three interior angles of that triangle",
          "An exterior angle is strictly less than either of its two adjacent supplementary angles",
          "An exterior angle of a triangle equals the sum of its two interior opposite angle values"
        ],
        "answer": 3,
        "explain": "Exterior Angle = Sum of Two Interior Opposite Angles (e.g., Exterior = Angle A + Angle B)!"
      },
      {
        "q": "In an EQUILATERAL TRIANGLE where all three angles are equal (x + x + x = 180°), what is the measure of each angle?",
        "options": [
          "50°",
          "60°",
          "90°",
          "45°"
        ],
        "answer": 1,
        "explain": "180 divided by 3 equal angles = exactly 60° for every angle in an equilateral triangle!"
      }
    ]
  },
