  "LO-298": {
    "title": "Exponential Power: Simplifying Mega Numbers 10ⁿ 🚀",
    "desc": "Uses exponential form of numbers to simplify problems involving multiplication and division of large numbers",
    "subSkill": "Exponents, Squares & Roots",
    "audio_script": "Astronomers use exponential powers of 10 to write cosmic distances: the speed of light is 3 x 10⁸ meters per second.",
    "story": "Astronomers use exponential powers of 10 to write cosmic distances: the speed of light is 3 x 10⁸ meters per second.",
    "instructions": [],
    "questions": [
      {
        "q": "Using the exponent law of multiplication (aᵐ x aⁿ = aᵐ⁺ⁿ), simplify: 10³ x 10⁵ =",
        "options": [
          "100⁸",
          "10²",
          "10¹⁵",
          "10⁸"
        ],
        "answer": 3,
        "explain": "When multiplying identical bases, add the exponents: 10³⁺⁵ = 10⁸!"
      },
      {
        "q": "Simplify using the exponent division law (aᵐ / aⁿ = aᵐ⁻ⁿ): 7⁶ / 7² =",
        "options": [
          "1⁴",
          "7³",
          "7⁸",
          "7⁴"
        ],
        "answer": 3,
        "explain": "When dividing matching bases, subtract powers: 7⁶⁻² = 7⁴!"
      },
      {
        "q": "What is the value of ANY non-zero number raised to the power of ZERO (a⁰)?",
        "options": [
          "The number itself",
          "Infinity",
          "Always 1",
          "0"
        ],
        "answer": 2,
        "explain": "By exponent division law: aⁿ / aⁿ = aⁿ⁻ⁿ = a⁰ = 1!"
      }
    ]
  },
