  "LO-299": {
    "title": "Fraction Division Decoded: Multiply by the Reciprocal 🍕🔄",
    "desc": "Interprets the division and multiplication of fractions",
    "subSkill": "Fractions, Decimals & Rational Numbers",
    "audio_script": "Chef Kabir has 3/4 kg of gourmet spice blend. He divides it into portions of 1/8 kg each to put into small glass jars.",
    "story": "Chef Kabir has 3/4 kg of gourmet spice blend. He divides it into portions of 1/8 kg each to put into small glass jars.",
    "instructions": [],
    "questions": [
      {
        "q": "How many 1/8 kg jars can Chef Kabir fill? Calculate: 3/4 ÷ 1/8.",
        "options": [
          "4 jars",
          "2 jars",
          "8 jars",
          "6 jars"
        ],
        "answer": 3,
        "explain": "Dividing by a fraction is multiplying by its reciprocal: 3/4 x 8/1 = 24/4 = 6 jars!"
      },
      {
        "q": "What is the 'RECIPROCAL' (multiplicative inverse) of the fraction 2/5?",
        "options": [
          "-2/5",
          "2/5",
          "5/2",
          "1/5"
        ],
        "answer": 2,
        "explain": "Flipping numerator and denominator yields the reciprocal: 2/5 x 5/2 = 1!"
      },
      {
        "q": "Solve: 2/3 x 9/10 =",
        "options": [
          "11/13",
          "1/2",
          "3/5",
          "18/13"
        ],
        "answer": 2,
        "explain": "(2 x 9)/(3 x 10) = 18/30. Dividing by 6/6 gives the simplified fraction 3/5!"
      }
    ]
  },
