  "LO-315": {
    "title": "Kinematics Graphing: Distance-Time Graphs 📈🚗",
    "desc": "Plots and interprets graphs (e.g., distance-time graph)",
    "subSkill": "Graphs",
    "audio_script": "A car travels along a highway: in 1 hour it covers 60 km, in 2 hours 120 km, in 3 hours 180 km. Students plot this data on graph paper.",
    "story": "A car travels along a highway: in 1 hour it covers 60 km, in 2 hours 120 km, in 3 hours 180 km. Students plot this data on graph paper.",
    "instructions": [],
    "questions": [
      {
        "q": "What does a STRAIGHT SLOPING LINE on a Distance-Time graph indicate about the motion of the vehicle?",
        "options": [
          "The vehicle is moving backwards",
          "The vehicle is moving with UNIFORM SPEED",
          "The vehicle is accelerating wildly",
          "The vehicle is stationary and parked"
        ],
        "answer": 1,
        "explain": "Equal distance covered in equal intervals of time produces a linear constant-slope graph (uniform speed)!"
      },
      {
        "q": "What does the SLOPE (gradient) of a Distance-Time graph represent physically?",
        "options": [
          "Total fuel consumed",
          "Speed",
          "Mass of the car",
          "Acceleration"
        ],
        "answer": 1,
        "explain": "Speed = Distance / Time! The steeper the slope of the line, the greater the speed of the moving body."
      },
      {
        "q": "If the Distance-Time line on graph paper becomes completely HORIZONTAL (flat parallel to time axis), what is the state of the object?",
        "options": [
          "The object is at REST",
          "The object is moving at light speed",
          "Time has stopped",
          "The object is falling down"
        ],
        "answer": 0,
        "explain": "Distance does not change as time advances, meaning the object is completely stationary!"
      }
    ]
  },
