  "LO-317": {
    "title": "Pendulum Physics: Time Periods & Oscillation 🕰️⚖️",
    "desc": "Measures and calculates temperature, pulse rate, speed of moving objects, time period of a simple pendulum, etc.",
    "subSkill": "Measurement & Calculation",
    "audio_script": "In 1583, Galileo Galilei timed the swinging chandelier in the Cathedral of Pisa using his own pulse, discovering the isochronism of the pendulum.",
    "story": "In 1583, Galileo Galilei timed the swinging chandelier in the Cathedral of Pisa using his own pulse, discovering the isochronism of the pendulum.",
    "instructions": [],
    "questions": [
      {
        "q": "What is the 'TIME PERIOD' (T) of a simple pendulum?",
        "options": [
          "The total mass of the suspended spherical pendulum bob measured in metric grams",
          "The maximum angle of displacement measured from the central resting vertical position",
          "The time taken by the pendulum bob to complete one full back-and-forth oscillation",
          "The total duration required for atmospheric friction to bring the pendulum to a stop"
        ],
        "answer": 2,
        "explain": "Time period is the duration required for one complete cyclic swing from extreme to extreme and back!"
      },
      {
        "q": "If a student counts 20 complete oscillations of a pendulum in 40 seconds, what is its Time Period?",
        "options": [
          "2.0 seconds",
          "20 seconds",
          "800 seconds",
          "0.5 seconds"
        ],
        "answer": 0,
        "explain": "Total time divided by number of oscillations: 40 / 20 = 2.0 seconds per oscillation!"
      },
      {
        "q": "What is the primary factor that determines the time period of a simple pendulum on Earth?",
        "options": [
          "How loud the room is",
          "The mass or material of the metal bob",
          "The color of the string",
          "The LENGTH of the suspending string"
        ],
        "answer": 3,
        "explain": "Formula: T = 2π√(L/g). Time period depends strictly on pendulum length L and gravitational acceleration g!"
      }
    ]
  },
