  "LO-319": {
    "title": "Giants of Science: Pasteur, Jenner & Fleming 🔬🧫",
    "desc": "Discusses and appreciates stories of scientific discoveries",
    "subSkill": "History of Scientific Discoveries",
    "audio_script": "In biology class, students explore how serendipity and brilliant observation led Edward Jenner to discover vaccination using cowpox.",
    "story": "In biology class, students explore how serendipity and brilliant observation led Edward Jenner to discover vaccination using cowpox.",
    "instructions": [],
    "questions": [
      {
        "q": "How did Dr. Edward Jenner create the world's FIRST VACCINE against deadly smallpox in 1796?",
        "options": [
          "He engineered the first compound electron microscope to observe bacterial cell division",
          "He used mild cowpox fluid from milkmaids to safely inoculate people against deadly smallpox",
          "He added concentrated chlorine salts to municipal well systems to eliminate waterborne germs",
          "He extracted synthetic penicillin antibiotics from blue bread mold to cure viral infections"
        ],
        "answer": 1,
        "explain": "From the Latin 'vacca' (cow), Jenner's cowpox inoculation gave birth to immunology and eradicated smallpox!"
      },
      {
        "q": "What food safety process, named after French microbiologist Louis Pasteur, heats milk to ~72°C for 15 seconds to kill pathogens?",
        "options": [
          "Freezing",
          "Pasteurization",
          "Fermentation",
          "Evaporation"
        ],
        "answer": 1,
        "explain": "Pasteurization destroys disease-causing bacteria (like tuberculosis and salmonella) without altering milk quality!"
      },
      {
        "q": "What life-saving antibiotic did Sir Alexander Fleming discover by chance when Penicillium notatum mold contaminated a bacterial petri dish?",
        "options": [
          "Paracetamol",
          "Insulin",
          "Penicillin",
          "Aspirin"
        ],
        "answer": 2,
        "explain": "Fleming noticed clear zones where mold secretions halted bacterial growth, launching the modern antibiotic era!"
      }
    ]
  },
