    "audio_script": "Students explore how internal plate tectonic collisions build towering mountains, while external winds, rivers, and glaciers sculpt majestic valleys.",
    "story": "Students explore how internal plate tectonic collisions build towering mountains, while external winds, rivers, and glaciers sculpt majestic valleys.",
    "instructions": [],
    "questions": [
      {
        "q": "What internal (endogenic) geological process formed the towering fold mountains of the HIMALAYAS?",
        "options": [
          "Extensive river deposition settling layers of fertile silt across the northern plains",
          "The colossal tectonic collision of the Indian Plate crashing northward into the Eurasian Continental Plate",
          "Tectonic divergence where two continental plates pulled apart to form a giant rift valley",
          "Violent volcanic eruptions spreading basaltic lava onto the Deccan Plateau"
        ],
        "answer": 1,
        "explain": "Plate tectonics! Over 50 million years, the collision of the Indian and Eurasian plates buckled ancient seabed sediments into the Himalayas!"
      },
      {
        "q": "What distinctive U-SHAPED valley landform is carved out by the slow, crushing movement of an alpine mountain GLACIER?",
        "options": [
          "A circular volcanic caldera formed by an explosive eruption",
          "A flat desert sand dune shaped by wind",
          "A sharp V-shaped river gorge cut by fast water",
          "A U-Shaped Glacial Trough"
        ],
        "answer": 3,
        "explain": "Glacial ice plucks and scours valley walls simultaneously, carving wide, steep, flat-bottomed U-shaped valleys!"
      },
      {
        "q": "What mushroom-shaped rock formations in arid deserts are created when wind erosion scours softer rock at the base faster than hard rock at the top?",
        "options": [
          "Sand dunes",
          "Mushroom Rocks",
          "Alluvial fans",
          "River oxbow lakes"
        ],
        "answer": 1,
        "explain": "Wind carrying abrasive sand grains stays close to the desert floor, eroding rock bases into slender stems topped by wide caps!"
      }
    ]
